/** 100 / 256. addIcon() forza `viewBox="0 0 100 100"`, Phosphor disegna su 256:
 *  senza questo wrapper i glifi verrebbero renderizzati ~2.5× fuori scala. */
const SCALE = '0.390625';

/** Il body SVG che addIcon() si aspetta: già scalato, già a currentColor.
 *  `fill` (non `stroke`) è ciò che rende il set "solid" — i glifi Phosphor
 *  fill sono forme piene, senza contorno.
 *
 *  `d` viene interpolato intero, mai spezzato: i path data contengono virgole
 *  e spazi, quindi qualsiasi split li frammenterebbe in glifi corrotti. */
function body(d: string): string {
  return `<g transform="scale(${SCALE})" fill="currentColor"><path d="${d}"/></g>`;
}

/** Quanti nomi Lucide questo modulo sovrascrive. */
export const MV_ICON_COUNT = 574;

/** Nomi Lucide coperti dall'override, per test e diagnostica. */
export const MV_ICON_NAMES: readonly string[] = Object.keys(PATHS);

/** `true` se il nome è coperto. Serve dove il nome arriva da config utente
 *  (le folder icon di Portal) e va validato prima dell'uso. */
export function mvHasIcon(name: string): boolean {
  return name in PATHS;
}

/** Registra ogni glifo nel registry di Obsidian. Va chiamata una sola volta,
 *  prima che qualunque view renderizzi. Non è reversibile a runtime. */
export function installMvIcons(): void {
  for (const [name, d] of Object.entries(PATHS)) addIcon(name, body(d));
}

/** Ridisegna le icone GIÀ presenti nel DOM che ora hanno un glifo nostro.
 *
 *  Serve perché `addIcon()` aggiorna il registry ma mai il DOM: qualunque
 *  icona disegnata prima di `installMvIcons()` resterebbe al glifo Lucide per
 *  tutta la sessione. Riguarda il chrome costruito all'avvio — ribbon, tab bar,
 *  view header — e le icone dei plugin che si caricano prima di questo.
 *
 *  Obsidian marca le sue icone Lucide con la classe `lucide-<nome>`, che è il
 *  modo di riconoscerle: le icone già passate dal registry non ce l'hanno, e
 *  vengono saltate (quindi la funzione è idempotente e non ricade su se stessa).
 *
 *  L'SVG viene sostituito, non ridisegnato sul parent: `setIcon(parent, …)`
 *  svuoterebbe il contenitore, e molti di questi parent contengono anche la
 *  label del bottone.
 *
 *  @returns quante icone sono state sostituite. */
export function refreshRenderedIcons(root: ParentNode = document): number {
  if (typeof (root as Element).querySelectorAll !== 'function') return 0;
  const stale = root.querySelectorAll<SVGElement>('svg.svg-icon[class*="lucide-"]');
  if (!stale.length) return 0;

  const scratch = document.createElement('div');
  let replaced = 0;
  for (const svg of Array.from(stale)) {
    const name = /(?:^|\s)lucide-([a-z0-9-]+)/.exec(svg.getAttribute('class') ?? '')?.[1];
    if (!name || !(name in PATHS)) continue;
    scratch.empty();
    setIcon(scratch, name);
    const fresh = scratch.firstElementChild;
    if (!fresh) continue;
    svg.replaceWith(fresh);
    replaced += 1;
  }
  return replaced;
}

